import{_ as s,a as t,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 单元 1 复习与自测 · 第19–24课","description":"L1–L24 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 1 复习与自测 · 第19–24课","description":"L1–L24 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-01/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 1 复习与自测","summary":"L1–L24 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 1 复习与自测 · 第10–18课","link":"/life/english/new-concept/book-2/unit-01/review-part-02"},"next":{"text":"第二册：实践与进步 · 单元 2：连接事件与解释选择","link":"/life/english/new-concept/book-2/unit-02/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 1 复习与自测 · 第10–18课","link":"/life/english/new-concept/book-2/unit-01/review-part-02"},"next":{"text":"第二册：实践与进步 · 单元 2：连接事件与解释选择","link":"/life/english/new-concept/book-2/unit-02/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/review-part-03.md","filePath":"life/english/new-concept/book-2/unit-01/review-part-03.md"}'),n={name:"life/english/new-concept/book-2/unit-01/review-part-03.md"};function i(l,e,r,p,h,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-1-复习与自测-·-第19–24课" tabindex="-1">第二册：实践与进步 · 单元 1 复习与自测 · 第19–24课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-复习与自测-·-第19–24课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1 复习与自测 · 第19–24课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-01/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-19-·-情态动词的意义与形式" tabindex="-1">Lesson 19 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-19-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 19 · 情态动词的意义与形式 {#lesson-19-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Two seats may become available if someone cancels.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>选 cancel/cancels：if someone ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cancels</p><p><strong>解析：</strong> 不定代词 someone 作主语时谓语按单数处理。</p></details><p><strong>表达迁移：</strong> 写一段购票经历，区分当时的可能性与最终买到的数量。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Two seats may become available if someone cancels. I left my phone number at the desk. An hour later, the clerk called with one spare ticket.</p><p>第一句的组织方式：may 修饰 become 表可能；if 从句 cancels 用现在时表达未来条件；someone 按单数处理。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-019">回看本课</a></p><h2 id="lesson-20-·-动名词与动词搭配" tabindex="-1">Lesson 20 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-20-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 20 · 动名词与动词搭配 {#lesson-20-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ben enjoys fishing beside the old bridge.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>填 fish 的形式：Ben enjoys ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fishing</p><p><strong>解析：</strong> enjoy 通常接动名词作宾语。</p></details><p><strong>表达迁移：</strong> 介绍一项不以结果为唯一目标的爱好，使用 enjoy doing 和一个动名词主语。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ben enjoys fishing beside the old bridge. He rarely catches anything. Listening to the water is enough for him.</p><p>第一句的组织方式：enjoys 是句子谓语，fishing 是作宾语的动名词，beside the old bridge 修饰 fishing 的地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-020">回看本课</a></p><h2 id="lesson-21-·-被动语态与信息重点" tabindex="-1">Lesson 21 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-21-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 21 · 被动语态与信息重点 {#lesson-21-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our sleep is disturbed by early flights.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 be：Our sleep ___ disturbed by early flights.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> sleep 在此为不可数名词，谓语用单数。</p></details><p><strong>表达迁移：</strong> 分析一个住处的优缺点，写清噪声、便利因素和自己的决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our sleep is disturbed by early flights. The rent is low, however. We have decided to stay until the end of the year.</p><p>第一句的组织方式：Our sleep 是承受影响的主语，is disturbed 是现在时被动，by early flights 表原因来源。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：noise 与 noisy 词性不同：traffic noise 是噪声，a noisy street 是吵闹的街道。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-021">回看本课</a></p><h2 id="lesson-22-·-动词、宾语与补足语" tabindex="-1">Lesson 22 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-22-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 22 · 动词、宾语与补足语 {#lesson-22-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A walker replied to the message inside the bottle.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>填介词：She replied ___ my message.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> reply 搭配 to 引出回复对象。</p></details><p><strong>表达迁移：</strong> 写一段意外收到旧消息的经历，交代发现、回复和反应。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A walker replied to the message inside the bottle. He found it during a walk along the coast. The writer had almost forgotten sending it.</p><p>第一句的组织方式：replied 是谓语，to the message 是必要的介词补足部分；inside the bottle 修饰 message 的所在位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：reply the message 通常应改为 reply to the message；answer the message 则不加 to。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-022">回看本课</a></p><h2 id="lesson-23-·-被动语态与信息重点" tabindex="-1">Lesson 23 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-23-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 23 · 被动语态与信息重点 {#lesson-23-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A new footpath is being built behind our house.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>补全进行时被动：The path is ___ built.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> being</p><p><strong>解析：</strong> 现在进行时被动结构为 is/are being done。</p></details><p><strong>表达迁移：</strong> 写一份三句工程进度说明，区分正在施工与预计完工。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A new footpath is being built behind our house. The builders expect to finish next month. Until then, we use the side gate.</p><p>第一句的组织方式：A new footpath 是主语，is being built 是现在进行时被动；behind our house 是地点，不是动作执行者。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：is building 表主动建造，不能让 footpath 像施工者一样行动；此处用 is being built。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-023">回看本课</a></p><h2 id="lesson-24-·-情态动词的意义与形式" tabindex="-1">Lesson 24 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-24-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 24 · 情态动词的意义与形式 {#lesson-24-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I lost my wallet, but someone returned it that evening.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>填 lose 的过去式：I ___ my wallet yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lost</p><p><strong>解析：</strong> lose 的过去式为 lost。</p></details><p><strong>表达迁移：</strong> 写一个有损失但结果尚可的小故事，准确说明丢了什么、找回什么。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I lost my wallet, but someone returned it that evening. The cash was gone. My cards and keys were still inside.</p><p>第一句的组织方式：lost 与 returned 同为过去式推进事件；someone 是未知身份的人，it 指 wallet，but 标记转折。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：someone 作主语按单数处理；someone have 应改为 someone has。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-024">回看本课</a></p>',52)])])}const m=s(n,[["render",i]]);export{g as __pageData,m as default};
